use vstd::prelude::*;

verus! {

/// Pure spec for clipping a single i8 value into [min, max].
spec fn clip_elem(x: i8, min: i8, max: i8) -> i8
    recommends min < max
{
    if x < min {
        min
    } else if x > max {
        max
    } else {
        x
    }
}

fn clip(a: Vec<i8>, min: i8, max: i8) -> (result: Vec<i8>)
    requires
        min < max,
    ensures
        result@.len() == a@.len(),
        forall|i: int|
            0 <= i < a@.len() ==>
                result@[i] == clip_elem(a@[i], min, max),
{
    let mut result: Vec<i8> = Vec::new();
    let mut i: usize = 0;

    while i < a.len()
        invariant
            min < max,
            i <= a@.len(),
            result@.len() == i as int,
            forall|j: int|
                0 <= j < i as int ==> result@[j] == clip_elem(a@[j], min, max),
        decreases a.len() - i,
    {
        let x = a[i];

        let y: i8;
        if x < min {
            y = min;
        } else if x > max {
            y = max;
        } else {
            y = x;
        }

        // Show the pushed value matches the spec clip function.
        assert(y == clip_elem(x, min, max));

        result.push(y);
        i = i + 1;
    }

    result
}

} // verus!

